param([Parameter(Mandatory=$true)][string]$InputPath,[Parameter(Mandatory=$true)][string]$OutputPath,[int]$Cutoff=6,[double]$Gamma=.85,[int]$Opacity=100)
Add-Type -ReferencedAssemblies 'System.Drawing.dll' -TypeDefinition @'
using System;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;
public static class MaskForgeEffect{public static void Convert(string input,string output,int cutoff,double gamma,int opacity){using(var s0=new Bitmap(input))using(var s=new Bitmap(s0.Width,s0.Height,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(s))g.DrawImageUnscaled(s0,0,0);var r=new Rectangle(0,0,s.Width,s.Height);var d=s.LockBits(r,ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);int n=Math.Abs(d.Stride)*s.Height;var p=new byte[n];Marshal.Copy(d.Scan0,p,0,n);s.UnlockBits(d);using(var o=new Bitmap(s.Width,s.Height,PixelFormat.Format32bppArgb)){var od=o.LockBits(r,ImageLockMode.WriteOnly,PixelFormat.Format32bppArgb);var q=new byte[Math.Abs(od.Stride)*o.Height];double th=Math.Min(.95,Math.Max(0,cutoff/255.0)),curve=Math.Max(.2,gamma),gain=Math.Max(0,opacity/100.0);for(int y=0;y<s.Height;y++)for(int x=0;x<s.Width;x++){int i=y*d.Stride+x*4,j=y*od.Stride+x*4;double b=p[i]/255.0,g=p[i+1]/255.0,rr=p[i+2]/255.0,dist=Math.Max(rr,Math.Max(g,b));double a=dist<=th?0:(dist-th)/Math.Max(.001,1-th);a=Math.Min(1,Math.Pow(a,curve)*gain)*(p[i+3]/255.0);if(a<=.0001)continue;q[j]=(byte)Math.Max(0,Math.Min(255,Math.Round(b/dist*255)));q[j+1]=(byte)Math.Max(0,Math.Min(255,Math.Round(g/dist*255)));q[j+2]=(byte)Math.Max(0,Math.Min(255,Math.Round(rr/dist*255)));q[j+3]=(byte)Math.Round(a*255);}Marshal.Copy(q,0,od.Scan0,q.Length);o.UnlockBits(od);o.Save(output,ImageFormat.Png);}}}}
'@
$src=(Resolve-Path -LiteralPath $InputPath).Path;$dst=[IO.Path]::GetFullPath($OutputPath);[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($dst))|Out-Null;[MaskForgeEffect]::Convert($src,$dst,$Cutoff,$Gamma,$Opacity)
